PROGRAM = 'BG = __BG__\n\n\ndef solve(demonstrations, grid):\n    h, w = len(grid), len(grid[0])\n    cy, cx = h // 2, w // 2\n    radius = min(cy, cx)\n    out = [row[:] for row in grid]\n    for y in range(h):\n        for x in range(w):\n            if y not in (0, h-1) and x not in (0, w-1):\n                continue\n            if (y, x) in ((0, cx), (h-1, cx), (cy, 0), (cy, w-1)):\n                continue  # Diamond vertices, not legend entries.\n            ink = grid[y][x]\n            if ink == BG:\n                continue\n            directions = []\n            if y == 0: directions.append((1, 0))\n            if y == h-1: directions.append((-1, 0))\n            if x == 0: directions.append((0, 1))\n            if x == w-1: directions.append((0, -1))\n            for dr, dc in directions:\n                r, c = y+dr, x+dc\n                entered = False\n                while 0 <= r < h and 0 <= c < w:\n                    # Geometry includes dust even when it has the wall colour.\n                    if abs(r-cy) + abs(c-cx) < radius:\n                        entered = True\n                        if grid[r][c] != BG:\n                            break\n                        out[r][c] = ink\n                    elif entered:\n                        break\n                    r, c = r+dr, c+dc\n    return out\n'

def build_program(d4, palette):
    return PROGRAM.replace('__BG__', str(int(palette[0])))
